class Rule {
  constructor(private readonly predicate: (value: number) => boolean, private readonly next?: Rule) {}
  handle(value: number): boolean {
    if (!this.predicate(value)) return false;
    return this.next ? this.next.handle(value) : true;
  }
}

const visits: number[] = [];
